const e = msg.error || {};
const src = (e.source && e.source.name) || 'unknown node';
const text = String(e.message || 'unknown error');
const key = text.slice(0, 80);
const now = Date.now();
const seen = flow.get('err_seen') || {};
for (const k of Object.keys(seen)) { if (now - seen[k] > 24*3600*1000) delete seen[k]; }
if (seen[key] && now - seen[key] < 2*3600*1000) { flow.set('err_seen', seen); return null; }
seen[key] = now;
flow.set('err_seen', seen);
msg.payload = {
    title: '⚠️ Portfolio Flow Error',
    message: src + ': ' + text,
    color: '#D32F2F',
    channel: 'Flow Errors'
};
return msg;

msg.finnhubToken = env.get('FINNHUB_TOKEN');
if (!msg.finnhubToken) {
    node.error('Finnhub self-test: FINNHUB_TOKEN env var is empty', msg);
    return null;
}
return msg;

const sc = msg.statusCode;
const d = msg.payload;
const ok = (sc === 200 && d && typeof d.c === 'number' && d.c > 0);
if (ok) {
    node.status({fill:'green',shape:'dot',text:'OK ' + new Date().toTimeString().slice(0,5)});
    if (msg._manualTest) {
        msg.payload = {
            title: '✅ Finnhub API OK',
            message: 'HTTP 200 - VOO $' + d.c.toFixed(2) + (typeof d.pc === 'number' ? ' (prev close $' + d.pc.toFixed(2) + ')' : ''),
            color: '#2E7D32',
            channel: 'Flow Errors'
        };
        return msg;
    }
    return null;
}
node.status({fill:'red',shape:'ring',text:'FAILED'});
node.error('Finnhub self-test FAILED (HTTP ' + sc + ', c=' + (d && d.c) + ') - quotes may be broken today', msg);
return null;
